public class MarketProduct {
    private String name;
    private String vendor;
    private double price;
    private String category;
    private String season;
    private boolean organic;

    public MarketProduct(String name, String vendor, double price,
                         String category, String season, boolean organic) {
        this.name = name;
        this.vendor = vendor;
        this.price = price;
        this.category = category;
        this.season = season;
        this.organic = organic;
    }

    public String getName() {
        return name;
    }

    public String getVendor() {
        return vendor;
    }

    public double getPrice() {
        return price;
    }

    public String getCategory() {
        return category;
    }

    public String getSeason() {
        return season;
    }

    public boolean isOrganic() {
        return organic;
    }

    @Override
    public String toString() {
        return String.format("%s (%s) - $%.2f [%s, %s, organic=%b]",
                name, vendor, price, category, season, organic);
    }
}
